var e={phone:`+91 462 000 1932`,phoneHref:`tel:+914620001932`,whatsapp:`+91 98765 01932`,whatsappHref:`https://wa.me/919876501932`,email:`care@ygasafoetida.in`,emailHref:`mailto:care@ygasafoetida.in`,hours:`Mon–Sat, 9am–6pm IST`,address:`Y.G Asafoetida Works, Tirunelveli, Tamil Nadu 627001`},t=[{id:`shipping-time`,keywords:[`ship`,`shipping`,`deliver`,`delivery`,`how long`,`days`,`dispatch`,`courier`,`arrive`],question:`How long does delivery take?`,answer:`We dispatch within 24 hours of your order from Tirunelveli. Standard delivery reaches most Indian pin codes in 2–6 working days; Express (₹99) usually lands in 1–2 days. You can watch every step on your order tracking page.`,followUps:[`Is shipping free?`,`Do you deliver to my pincode?`]},{id:`shipping-free`,keywords:[`free shipping`,`shipping charge`,`delivery charge`,`shipping cost`,`free over`,`₹499`,`499`],question:`Is shipping free?`,answer:`Shipping is free on every order above ₹499. Below that a flat ₹49 applies. Express shipping is ₹99 on top, and Cash on Delivery adds a ₹20 handling fee.`},{id:`pincode`,keywords:[`pincode`,`pin code`,`my area`,`serviceable`,`location`,`all india`],question:`Do you deliver to my pincode?`,answer:`We ship to all serviceable pin codes across India. Enter your 6-digit PIN at checkout — we auto-fill your city and state and confirm serviceability right there.`},{id:`which-product`,keywords:[`which`,`recommend`,`start`,`beginner`,`difference`,`powder or`,`best for me`,`suggest`],question:`Which hing should I buy?`,answer:`Premium Compounded Powder for everyday sambar, rasam and tempering. Granules for curd rice, buttermilk and pickles — they bloom slowly. Gold Cake for festive kuzhambu when you want the strongest aroma. If you're unsure, start with the powder twin-pack (₹199).`,followUps:[`Is it gluten-free?`,`How much should I use?`]},{id:`gluten`,keywords:[`gluten`,`wheat`,`allergy`,`allergen`,`celiac`,`coeliac`],question:`Is your hing gluten-free?`,answer:`Our YG Gluten-Free Hing Powder uses a rice-starch base with no wheat. The classic compounded powder, granules and cake use edible starch that may contain wheat, so choose the gluten-free line if you are avoiding gluten.`},{id:`usage`,keywords:[`how much`,`quantity`,`use`,`usage`,`pinch`,`recipe`,`cook`,`tempering`],question:`How much hing should I use?`,answer:`About a quarter teaspoon of powder into hot ghee at the tempering stage serves a family pot of sambar or rasam. For granules, crush a pinch. For the cake, scrape a pea-sized piece. Hing is strong — less is more.`},{id:`ingredients`,keywords:[`ingredient`,`made of`,`contains`,`compounded`,`pure`,`additive`,`preservative`],question:`What is compounded hing made of?`,answer:`Compounded asafoetida is resin blended with edible starch and edible gum — that's what makes it pourable and safe to use by the pinch. No artificial colours or preservatives are added.`},{id:`shelf-life`,keywords:[`shelf life`,`expiry`,`expire`,`store`,`storage`,`how to keep`,`airtight`],question:`How should I store it and how long does it last?`,answer:`Keep the jar tightly closed in a cool, dry cupboard away from steam. All products have an optimal shelf life of 12 months from packing. Store in an airtight container.`},{id:`order-track`,keywords:[`track`,`where is my order`,`status`,`order status`,`tracking`],question:`How do I track my order?`,answer:`Open Account → Order history and tap any order, or use the tracking link on your confirmation screen. You'll see a live timeline from 'Packed in Tirunelveli' through to 'Delivered', plus an estimated delivery date.`},{id:`cancel`,keywords:[`cancel`,`cancellation`,`stop my order`,`change order`],question:`Can I cancel my order?`,answer:`Yes — cancellation is free and instant any time before the order is marked Shipped. Open the order tracking page and tap 'Cancel order'. Once it has been dispatched, use 'Request refund' instead.`,followUps:[`How do refunds work?`]},{id:`refund`,keywords:[`refund`,`return`,`money back`,`damaged`,`wrong item`,`replace`],question:`How do refunds work?`,answer:`Refund requests are accepted from dispatch until 7 days after delivery. Choose a reason on the order page and we review within 24 hours. Approved refunds go back to your original payment method within 7 working days (3 for cancellations). COD orders are refunded by bank transfer.`},{id:`promo`,keywords:[`promo`,`coupon`,`discount`,`code`,`offer`,`cheaper`,`sale`],question:`Do you have discount codes?`,answer:`Yes. HERITAGE10 gives 10% off, HING50 takes ₹50 off orders above ₹399, and FREESHIP removes the delivery fee. Orders above ₹999 automatically get BULK15 (15% off) whenever it beats your typed code.`},{id:`payment`,keywords:[`payment`,`pay`,`upi`,`card`,`cod`,`cash on delivery`,`netbanking`,`paytm`],question:`What payment methods do you accept?`,answer:`Paytm, UPI (GPay/PhonePe/BHIM), credit and debit cards, net banking, and Cash on Delivery (₹20 handling fee).`},{id:`bulk`,keywords:[`bulk`,`wholesale`,`restaurant`,`distributor`,`export`,`reseller`,`b2b`],question:`Do you supply in bulk?`,answer:`Yes — restaurants, retailers, caterers and exporters are welcome. Write to ${e.email} with your quantity and city and our team will send wholesale pricing.`},{id:`history`,keywords:[`1932`,`history`,`story`,`founder`,`family`,`heritage`,`who are you`,`about`],question:`Who makes Y.G Asafoetida?`,answer:`Shri P. Subramanian Chettiar started the works near Tirunelveli in 1932. Ninety-plus years later the founder's grandchildren still run it from the same town, using the same house formula. Read the full story on our Story page.`},{id:`gift`,keywords:[`gift`,`wrap`,`present`,`message card`],question:`Can I send this as a gift?`,answer:`Yes — tick heritage gift wrap at checkout (₹49) and add a handwritten-style message. We leave the price off the packing slip.`},{id:`location`,keywords:[`address`,`where are you`,`shop`,`store`,`visit`,`factory`,`map`,`office`],question:`Where are you located?`,answer:`${e.address}. Our works and office are open ${e.hours} — there's a map on the Contact page if you'd like to visit.`}],n=new Set([`the`,`a`,`an`,`is`,`are`,`do`,`does`,`i`,`my`,`you`,`your`,`to`,`of`,`for`,`and`,`in`,`on`,`it`,`can`,`how`,`what`,`when`,`please`,`hing`]);function r(e){let r=e.toLowerCase().trim();if(!r)return{text:`Ask me anything about products, delivery, refunds or offers.`,matched:!0,followUps:[]};if(/^(hi|hello|hey|vanakkam|namaste|hai)\b/.test(r))return{text:`Vanakkam! I'm the Y.G helper — a simple rule-based FAQ bot. Ask me about products, delivery, offers, cancellations or refunds.`,matched:!0,followUps:[`Which hing should I buy?`,`Is shipping free?`,`How do refunds work?`]};if(/(thank|thanks|nandri|super|great)\b/.test(r))return{text:`Happy to help. Anything else you'd like to know?`,matched:!0,followUps:[]};let i=r.split(/[^a-z0-9₹]+/).filter(e=>e.length>2&&!n.has(e)),a=null,o=0;for(let e of t){let t=0;for(let n of e.keywords)n.includes(` `)?r.includes(n)&&(t+=3):i.includes(n)?t+=2:i.some(e=>e.startsWith(n)||n.startsWith(e))&&(t+=1);t>o&&(o=t,a=e)}return!a||o<2?{text:`I don't know that one — I'm only a basic FAQ bot, so I can't look up your specific account or order details.`,matched:!1,followUps:[]}:{text:a.answer,matched:!0,followUps:a.followUps??[]}}var i=[`Which hing should I buy?`,`Is shipping free?`,`Can I cancel my order?`,`Do you have discount codes?`,`Is it gluten-free?`];export{i,r as n,t as r,e as t};